package main

import (
	"crypto/subtle"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"
	"sync"
)

// ModelConfig represents inference configuration
type ModelConfig struct {
	BatchSize    int                    `json:"batch_size"`
	Timeout      int                    `json:"timeout_ms"`
	DeviceID     int                    `json:"device_id"`
	Extensions   map[string]interface{} `json:"extensions"`
}

// ConnectionPool manages model inference connections
type ConnectionPool struct {
	mu       sync.RWMutex
	defaults map[string]interface{}
	pools    map[string]*PoolEntry
}

type PoolEntry struct {
	Config   map[string]interface{}
	Active   int
	MaxConns int
}

var globalPool = &ConnectionPool{
	defaults: map[string]interface{}{
		"batch_size":  32,
		"timeout_ms":  5000,
		"device_id":   0,
		"max_retries": 3,
		"auth_bypass": false,
		"admin_mode":  false,
	},
	pools: make(map[string]*PoolEntry),
}

// deepMerge merges src into dst recursively
func deepMerge(dst, src map[string]interface{}) map[string]interface{} {
	for key, srcVal := range src {
		if dstVal, exists := dst[key]; exists {
			if dstMap, ok := dstVal.(map[string]interface{}); ok {
				if srcMap, ok := srcVal.(map[string]interface{}); ok {
					deepMerge(dstMap, srcMap)
					continue
				}
			}
		}
		dst[key] = srcVal
	}
	return dst
}

// resolveConfig builds effective config by merging defaults with overrides
func (cp *ConnectionPool) resolveConfig(modelID string, overrides map[string]interface{}) map[string]interface{} {
	cp.mu.RLock()
	defer cp.mu.RUnlock()

	// Start with a copy of defaults
	effective := make(map[string]interface{})
	for k, v := range cp.defaults {
		effective[k] = v
	}

	// Apply model-specific pool config if exists
	if entry, ok := cp.pools[modelID]; ok {
		deepMerge(effective, entry.Config)
	}

	// Apply user overrides - only allow safe keys
	safeOverrides := filterSafeKeys(overrides)
	deepMerge(effective, safeOverrides)

	return effective
}

// filterSafeKeys returns only configuration keys that users are allowed to override
func filterSafeKeys(input map[string]interface{}) map[string]interface{} {
	allowedKeys := map[string]bool{
		"batch_size":  true,
		"timeout_ms":  true,
		"device_id":   true,
	}
	filtered := make(map[string]interface{})
	for k, v := range input {
		if allowedKeys[k] {
			// Only allow primitive numeric values for these keys
			switch v.(type) {
			case float64, int:
				filtered[k] = v
			}
		}
	}
	return filtered
}

// updateDefaults allows updating the shared default configuration
func (cp *ConnectionPool) updateDefaults(patch map[string]interface{}) {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	deepMerge(cp.defaults, patch)
}

// validAdminToken performs a safe, constant-time comparison of the provided
// token against the configured admin secret. Returns false if no secret is
// configured to avoid accidental auth bypass.
func validAdminToken(token string) bool {
	secret := getAdminSecret()
	if secret == "" {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(token), []byte(secret)) == 1
}

func handleInference(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var request struct {
		ModelID  string                 `json:"model_id"`
		Inputs   []float64              `json:"inputs"`
		Config   map[string]interface{} `json:"config"`
	}

	if err := json.NewDecoder(r.Body).Decode(&request); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	if request.ModelID == "" || !isValidModelID(request.ModelID) {
		http.Error(w, "invalid model_id", http.StatusBadRequest)
		return
	}

	// Resolve effective configuration
	effective := globalPool.resolveConfig(request.ModelID, request.Config)

	// Check authorization
	if adminMode, ok := effective["admin_mode"].(bool); ok && adminMode {
		token := r.Header.Get("X-Admin-Token")
		if !validAdminToken(token) {
			http.Error(w, "unauthorized admin access", http.StatusForbidden)
			return
		}
	}

	// Simulate inference
	result := runInference(request.Inputs, effective)

	// Only return safe config keys in response
	safeConfig := map[string]interface{}{
		"batch_size":  effective["batch_size"],
		"timeout_ms":  effective["timeout_ms"],
		"device_id":   effective["device_id"],
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"model_id": request.ModelID,
		"result":   result,
		"config":   safeConfig,
	})
}

func handlePoolConfig(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Only admin can update pool defaults
	token := r.Header.Get("X-Admin-Token")
	if !validAdminToken(token) {
		http.Error(w, "unauthorized", http.StatusForbidden)
		return
	}

	var patch map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&patch); err != nil {
		http.Error(w, "invalid body", http.StatusBadRequest)
		return
	}

	globalPool.updateDefaults(patch)
	w.WriteHeader(http.StatusOK)
}

func isValidModelID(id string) bool {
	if len(id) > 64 {
		return false
	}
	for _, c := range id {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_') {
			return false
		}
	}
	return true
}

// getAdminSecret reads the admin token from the environment rather than
// embedding it in source code.
func getAdminSecret() string {
	return os.Getenv("ADMIN_TOKEN")
}

func runInference(inputs []float64, config map[string]interface{}) []float64 {
	batchSize := 32
	if bs, ok := config["batch_size"].(float64); ok {
		batchSize = int(bs)
	}
	_ = batchSize
	// Simulated inference result
	results := make([]float64, len(inputs))
	for i, v := range inputs {
		results[i] = v * 0.5
	}
	return results
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/inference", handleInference)
	mux.HandleFunc("/v1/pool/config", handlePoolConfig)

	server := &http.Server{
		Addr:    ":8080",
		Handler: mux,
	}

	fmt.Println("ML Inference Server starting on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
	_ = strings.Contains("", "")
}
